L.append("            <div className=\"space-y-2\">{(() => { const zInv: Record<string, number> = {}; " + VAR + ".forEach((r) => { zInv[r.zone] = (zInv[r.zone] || 0) + r.investmentCr; }); return Object.entries(zInv).sort((a, b) => b[1] - a[1]).map(([zone, inv]) => { const pct = (inv as number / kpiData.total) * 100; return <div key={zone} className=\"flex items-center gap-2\"><span className=\"text-xs w-16\">{zone as string}</span><div className=\"flex-1 h-2 bg-muted rounded-full\"><div className=\"h-2 rounded-full\" style={{ width: `${pct}%`, backgroundColor: themeColor }} /></div><span className=\"text-xs font-medium\">&#8377;{inv as number}Cr</span></div>; }); })()}</div>")
L.append("          </CardContent></Card>")
L.append("          <Card><CardHeader><CardTitle className=\"text-base\">Purity Distribution</CardTitle></CardHeader><CardContent>")
L.append("            <div className=\"space-y-2\">")
L.append("              {(() => { const ranges = { '99.5%+': 0, '99-99.4%': 0, '96-98.9%': 0, '<96%': 0 }; " + VAR + ".forEach((r) => { if (r.purityPercent >= 99.5) ranges['99.5%+']++; else if (r.purityPercent >= 99) ranges['99-99.4%']++; else if (r.purityPercent >= 96) ranges['96-98.9%']++; else ranges['<96%']++; }); return (Object.entries(ranges) as [string, number][]).filter(([, v]) => v > 0).map(([range, count]) => { const pct = (count / " + VAR + ".length) * 100; return <div key={range} className=\"flex items-center gap-2\"><span className=\"text-xs w-24\">{range}</span><div className=\"flex-1 h-2 bg-muted rounded-full\"><div className=\"h-2 rounded-full\" style={{ width: `${pct}%`, backgroundColor: themeColor }} /></div><span className=\"text-xs font-medium\">{count}</span></div>; }); })()}")
L.append("            </div>")
L.append("          </CardContent></Card>")
L.append("        </div>")
L.append("      )}")
# Insights
L.append("      {activeTab === 'insights' && (")
L.append("        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-4\">")
L.append("          <Card><CardHeader><CardTitle className=\"text-base\">Supply Chain Intelligence</CardTitle></CardHeader><CardContent><div className=\"space-y-3 text-sm\">")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Nuclear Absorber Demand</div><div className=\"text-xs text-muted-foreground mt-1\">NPCIL PHWR 700 and BARC research reactor programme driving 99.9% chromia absorber &#8594; &#8377;940Cr for 400 tonnes &#8594; critical national security</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Space TPS Growth</div><div className=\"text-xs text-muted-foreground mt-1\">ISRO RLV and GSLV Mk3 expansion &#8594; chromia ceramic TPS + NAL TBC &#8594; &#8377;1,640Cr combined for aerospace coatings</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Defence Camouflage</div><div className=\"text-xs text-muted-foreground mt-1\">BEL DRDO NIR camouflage netting and vehicle paint &#8594; chromia green pigment military specification &#8594; &#8377;580Cr for 1,200 tonnes</div></div>")
