L.append("          </div></CardContent></Card>")
L.append("          <Card><CardHeader><CardTitle className=\"text-base\">Investment Landscape</CardTitle></CardHeader><CardContent><div className=\"space-y-3 text-sm\">")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Total Portfolio: &#8377;{kpiData.total.toLocaleString()} Cr</div><div className=\"text-xs text-muted-foreground mt-1\">Across 14 chromia grades spanning coatings, refractory, aerospace, defence, abrasive, glass, welding, tanning, naval and nuclear &#8594; avg purity {kpiData.avgPurity}%</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Critical Priority: 4 Records</div><div className=\"text-xs text-muted-foreground mt-1\">ISRO TPS &#8594; CSIR-NAL TBC &#8594; GRSE submarine &#8594; NPCIL absorber &#8594; strategic programmes</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Top Applications</div><div className=\"text-xs text-muted-foreground mt-1\">Nuclear absorber &#8594; aerospace TPS/TBC &#8594; automotive coating &#8594; steel refractory &#8594; abrasive grinding &#8594; 5 sectors above &#8377;600Cr</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-violet-500 bg-violet-50/50\"><div className=\"font-medium\">Import Dependency</div><div className=\"text-xs text-muted-foreground mt-1\">High-purity 99.5%+ chromia still 40% imported &#8594; Sukinda chromite expansion and UP Chrome capacity ramp critical for Atmanirbhar</div></div>")
L.append("          </div></CardContent></Card>")
L.append("        </div>")
L.append("      )}")
L.append("    </div>")
L.append("  );")
L.append("}")
L.append("")

content = "\n".join(L)

import re
bad = [e for e in re.findall(r'&#(\d+);', content) if int(e) > 9999]
if bad:
    print(f"WARNING: bad entities: {bad}")
else:
    print(f"OK: {len(re.findall(r'&#(\d+);', content))} entities, all clean")

with open(OUTPUT, "w") as f:
    f.write(content)
print(f"Generated {OUTPUT} ({len(L)} lines)")
print(f"Records: {len(RECORDS)}, Total: {sum(r[8] for r in RECORDS)} Cr, Avg purity: {sum(r[6] for r in RECORDS)/len(RECORDS):.2f}%")
